// The golden message fixtures of PRO-110 (packages/tck/fixtures/messages/messages.json, generated by
// packages/tck/scripts/generate.ts) round-trip through the DEP codec: decode(encode(x)) equals x for
// every valid frame of every message type (PRO-004, criterion 3). Invalid frames are refused.
import { describe, expect, it } from 'vitest';
import { depCodec } from '../src/codec/frame.ts';
import type { Receiver } from '../src/codec/frame.ts';
import { readJson } from './support.ts';

interface Golden {
  t: string;
  dir: 'c2s' | 's2c' | 'both';
  valid: Array<{ name: string; frame: Record<string, unknown> }>;
  invalid: Array<{ name: string; frame: unknown }>;
}

const fixtures = readJson<{ messages: Golden[] }>('packages/tck/fixtures/messages/messages.json');
const codec = depCodec();

/** The side that receives a frame of this direction (05 §5): c2s is read by a server. */
function receiversOf(dir: Golden['dir']): Receiver[] {
  if (dir === 'c2s') return ['server'];
  if (dir === 's2c') return ['client'];
  return ['server', 'client'];
}

describe('golden message fixtures (PRO-110, PRO-004)', () => {
  it('covers every message type of the definition', () => {
    expect(fixtures.messages.length).toBeGreaterThanOrEqual(28);
    for (const g of fixtures.messages) {
      expect(g.valid.length).toBeGreaterThan(0);
      expect(g.invalid.length).toBeGreaterThan(0);
    }
  });

  for (const g of fixtures.messages) {
    it(`round-trips every valid ${g.t} frame: decode(encode(x)) equals x`, () => {
      for (const v of g.valid) {
        const text = codec.encode(v.frame as never);
        for (const receiver of receiversOf(g.dir)) {
          const r = codec.decode(text, { receiver });
          expect(r, `${g.t} / ${v.name} as ${receiver}`).toEqual({
            kind: 'message',
            message: v.frame,
          });
        }
      }
    });
  }

  for (const g of fixtures.messages) {
    it(`refuses every invalid ${g.t} frame`, () => {
      for (const v of g.invalid) {
        const text = JSON.stringify(v.frame);
        for (const receiver of receiversOf(g.dir)) {
          const r = codec.decode(text, { receiver });
          expect(r.kind, `${g.t} / ${v.name} as ${receiver}`).not.toBe('message');
        }
      }
    });
  }
});
